(() => {
  'use strict';
  const BASE = 'https://woongbi-quote-api.woongbts.workers.dev';
  const $ = id => document.getElementById(id);
  const won = value => Number.isFinite(Number(value)) ? Math.max(0, Math.round(Number(value))).toLocaleString('ko-KR') + '원' : '—';
  const purposeNames = {senior:'효도폰', kids:'키즈폰', value:'가성비폰', premium:'프리미엄폰'};
  const methodMemory = new Map();
  let purposeSeq = 0, quickSeq = 0, purposeTimer = 0;
  let applyingPurpose = false, applyingQuick = false;

  const style = document.createElement('style');
  style.textContent = `
    .wb-server-card{position:relative}.wb-server-compare{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.wb-server-compare button{appearance:none;text-align:left;padding:10px;border:1px solid #dfe8eb;border-radius:12px;background:#fff;color:inherit;cursor:pointer}.wb-server-compare button:disabled{cursor:default;opacity:.58}.wb-server-compare button.selected{border-color:#79c9a6;background:#f1fbf6}.wb-server-compare small,.wb-server-compare b,.wb-server-compare span{display:block}.wb-server-compare small{color:#74858b;font-size:.7rem}.wb-server-compare b{margin-top:3px;font-size:.84rem;color:#163d4a}.wb-server-compare span{margin-top:4px;font-size:.68rem;color:#55717a}.wb-server-why{margin:12px 0 0;padding:12px 13px;border-radius:14px;background:#f5f8f9;color:#405b64;font-size:.8rem;line-height:1.55}.wb-server-why strong{display:block;color:#153e4d;margin-bottom:3px}.wb-server-reason{margin:8px 0;color:#526b73;font-size:.82rem;line-height:1.5}.wb-server-specs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px 0}.wb-server-specs>span{border:1px solid #dce8ec;border-radius:12px;padding:9px;background:#fbfdfe}.wb-server-specs small,.wb-server-specs b{display:block}.wb-server-specs small{color:#70838a;font-size:.7rem;margin-bottom:4px}.wb-server-specs b{font-size:.82rem;color:#173842;line-height:1.35}@media(max-width:560px){.wb-server-specs{grid-template-columns:1fr}.wb-server-compare{grid-template-columns:1fr 1fr}}
  `;
  document.head.appendChild(style);

  async function post(path, body) {
    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const timeout = controller ? setTimeout(() => controller.abort(), 8000) : 0;
    try {
      const response = await fetch(BASE + path, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body), signal:controller?.signal});
      if (!response.ok) throw Error('recommend-api-' + response.status);
      const data = await response.json();
      if (!data || data.ok !== true) throw Error('recommend-api-invalid');
      return data;
    } finally { if (timeout) clearTimeout(timeout); }
  }

  function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = String(text);
    return node;
  }
  function addRow(parent, label, value, className='') {
    const row = el('div', className);
    row.append(el('span','',label), el('b','',value));
    parent.append(row);
    return row;
  }
  function imageFor(device, className) {
    const src = typeof window.woongbiDeviceImage === 'function' ? window.woongbiDeviceImage(device) : '';
    if (!src) return null;
    const frame = el('div', `device-card-image ${className}`);
    const img = document.createElement('img');
    img.src = src; img.alt = device?.name || '휴대폰'; img.loading = 'lazy'; img.decoding = 'async';
    img.addEventListener('error', () => frame.remove(), {once:true});
    frame.append(img);
    return frame;
  }
  function dispatch(node, type) { node?.dispatchEvent(new Event(type, {bubbles:true})); }

  function directUrl(item, joinType) {
    if (!item?.d?.id || !item?.p?.id) return '/rates.html';
    const q=new URLSearchParams();
    item.d.carrier&&q.set('c',item.d.carrier);
    q.set('j',joinType||item.joinLabel||'기기변경');
    if(['support','contract'].includes(item.best?.method))q.set('m',item.best.method);
    q.set('d',item.d.id);
    q.set('p',item.p.id);
    q.set('mo','24');
    if(item.welfare&&item.welfare!=='none')q.set('w',item.welfare);
    return '/rates.html?'+q.toString();
  }
  function openDirect(item, joinType) {
    location.assign(directUrl(item,joinType));
  }

  function purposeState() {
    const active = document.querySelector('[data-purpose-category].active');
    return {category:active?.dataset.purposeCategory || 'senior', carrier:$('purpose-carrier')?.value || 'all', join_type:$('purpose-join')?.value || '기기변경', basic_pension:Boolean($('purpose-pension')?.checked)};
  }

  function consultText(item, category, join, selected) {
    const method = item.kidsPromo ? '신규가입 특가' : selected?.method === 'support' ? '공시지원금' : '선택약정 25%';
    const lines = ['[웅비통신 자동 추천 상담]', `용도: ${purposeNames[category] || '휴대폰'}`];
    if (item.lane) lines.push(`추천 이유: ${item.lane}`);
    lines.push(`통신사: ${item.d?.carrier || '확인 필요'}`, `가입유형: ${join}`, `기종: ${item.d?.name || '확인 필요'}`, `요금제: ${item.p?.name || '확인 필요'} / ${won(item.p?.monthly_fee)}`, `선택한 할인방식: ${method}`, `예상 월 납부액: ${won(selected?.monthly)}`);
    if (selected?.total24 != null) lines.push(`24개월 예상 총부담: ${won(selected.total24)}`);
    if (selected?.method === 'support') lines.push(`적용 공시지원금: ${won(selected.support)}`);
    if (selected?.method === 'contract') lines.push(`선택약정 월 할인: ${won(selected.contractDiscount)}`);
    if (item.welfare === 'basic_pension') lines.push(`기초연금 할인 반영: -${won(selected?.welfare?.amount || 0)}`);
    if (item.kidsPromo) lines.push('기기값: 0원 행사', '※ 신규가입 한정 · 해당 요금제 및 행사 조건 기준');
    lines.push('매장 추가지원금·가족/인터넷 결합 미반영', '※ 실제 가입 가능 여부·자격·지원금·재고·프로모션은 상담 시점에 최종 확인합니다.');
    return lines.join('\n');
  }

  function premiumLineup(device) {
    const text = `${device?.name || ''} ${device?.model_code || ''}`.toLowerCase().replace(/\s+/g,'');
    if (/s26ultra/.test(text)) return '갤럭시 S26 시리즈 · Ultra';
    if (/s26\+|s26plus/.test(text)) return '갤럭시 S26 시리즈 · S26+';
    if (/갤럭시s26|galaxys26|s26/.test(text)) return '갤럭시 S26 시리즈 · S26';
    if (/폴드8|fold8/.test(text)) return '갤럭시 Z 폴더블8 · Fold8';
    if (/플립8|flip8/.test(text)) return '갤럭시 Z 폴더블8 · Flip8';
    if (/아이폰18|iphone18/.test(text)) return 'iPhone 18 시리즈';
    return '';
  }

  function renderPurpose(data, state) {
    const target = $('purpose-results');
    if (!target) return;
    applyingPurpose = true;
    const note = $('purpose-category-note');
    if (note && data.description) note.textContent = data.description;
    target.innerHTML = '';
    const items = Array.isArray(data.items) ? data.items : [];
    if (!items.length) {
      target.append(el('p','', '현재 등록된 데이터에서 이 조건에 맞는 조합을 찾지 못했습니다. 통신사나 가입유형을 바꾸거나 직접 계산을 이용해 주세요.'));
      setTimeout(() => { applyingPurpose=false; }, 0); return;
    }

    items.forEach((item, index) => {
      const join = item.joinLabel || state.join_type || '기기변경';
      const key = [item.d?.id, item.p?.id, join, item.welfare || 'none'].join('|');
      let selected = item.best;
      const remembered = methodMemory.get(key);
      if (remembered === 'support' && item.support?.known) selected = item.support;
      if (remembered === 'contract' && item.contract?.known) selected = item.contract;

      const card = el('article', item.kidsPromo ? 'purpose-card kids-sale-card wb-server-card' : 'purpose-card wb-server-card');
      card.dataset.deviceId = item.d?.id || '';
      card.dataset.planId = item.p?.id || '';
      const top = el('div','purpose-card-top');
      top.append(el('span','', `${item.d?.carrier || ''} · ${join}`));
      top.append(el('small','', item.kidsPromo ? (item.promoLabel || 'SALE') : (item.lane || (index === 0 ? '추천 조합' : '비교 후보'))));
      card.append(top);
      const picture = imageFor(item.d, 'purpose-device-image'); if (picture) card.append(picture);
      card.append(el('strong','', item.d?.name || '휴대폰'));
      if (state.category === 'premium') { const line = premiumLineup(item.d); if (line) card.append(el('span','purpose-lineup',line)); }
      card.append(el('em','', item.p?.name || '요금제 확인'));
      if (Array.isArray(item.reasons) && item.reasons.length) card.append(el('p','wb-server-reason', item.reasons.find(reason => !reason.includes('24개월 기준') && !reason.includes('기준 계산')) || item.reasons[0]));

      if (item.kidsPromo) {
        const deal = el('div','kids-zero-deal');
        deal.append(el('span','',item.promoLabel || 'SALE'), el('strong','',item.promoText || '기기값 0원 행사'), el('small','','신규가입 한정 · 해당 요금제 기준'));
        card.append(deal);
      }

      const total = el('div','purpose-card-total');
      const totalLabel = el('span'); const totalValue = el('b'); total.append(totalLabel,totalValue); card.append(total);
      card.append(el('p','quote-amount-note', item.kidsPromo ? '신규가입 행사 기준 · 재고와 최종 조건은 상담으로 확인' : '매장 추가지원금·가족/인터넷 결합 미반영 · 최종 조건은 상담으로 확인'));
      const specs = el('div','wb-server-specs');
      [['데이터',item.p?.data],['통화',item.p?.voice]].forEach(([label,value]) => { const spec=el('span'); spec.append(el('small','',label),el('b','',value || '확인 필요')); specs.append(spec); });
      card.append(specs);

      const details = el('details','recommend-details'); details.append(el('summary','','요금 구성·할인 비교 자세히 보기'));
      const body = el('div','recommend-details-body');
      const detail = el('div','purpose-card-detail'); body.append(detail);
      const compare = el('div', item.kidsPromo ? 'purpose-method-compare kids-sale-condition' : 'wb-server-compare');
      const choices = [];
      if (item.kidsPromo) compare.textContent = '신규가입 한정 특가 · 재고 및 행사 조건은 상담 시 최종 확인';
      else [['공시지원금',item.support],['선택약정 25%',item.contract]].forEach(([label,quote]) => {
        const button=el('button'); button.type='button'; button.disabled=!quote?.known;
        const small=el('small','',label), bold=el('b','',quote?.known ? `월 ${won(quote.monthly)}` : '매장 확인'), status=el('span');
        button.append(small,bold,status); compare.append(button); choices.push({button,status,quote});
        button.addEventListener('click', () => { if (!quote?.known) return; selected=quote; methodMemory.set(key, quote.method); refresh(); });
      });
      body.append(compare);
      const why = el('div','wb-server-why');
      if (!item.kidsPromo && item.lane) { why.append(el('strong','',`왜 ${item.lane}인가요?`), el('span','',Array.isArray(item.reasons) && item.reasons.length ? item.reasons.join(' · ') : '현재 조건에서 월 부담과 기기 조건을 함께 비교한 추천입니다.')); body.append(why); }
      details.append(body); card.append(details);

      const actions=el('div','purpose-card-actions');
      if (!item.kidsPromo) { const detailButton=el('button','','조건 바꿔 계산'); detailButton.type='button'; detailButton.addEventListener('click',()=>openDirect({...item,best:selected},join)); actions.append(detailButton); }
      const consult=el('button','primary',item.kidsPromo ? '이 특가 상담' : '이 조건으로 상담'); consult.type='button'; if (item.kidsPromo) consult.style.gridColumn='1 / -1'; consult.addEventListener('click',()=>window.WoongbiQuoteHandoff?.open(consultText(item,state.category,join,selected))); actions.append(consult); card.append(actions);

      function refresh() {
        const method = item.kidsPromo ? '신규가입 특가' : selected?.method === 'support' ? '공시지원금' : '선택약정 25%';
        totalLabel.textContent = `예상 월 납부액 · ${method}${item.welfare === 'basic_pension' ? ' · 기초연금 할인 포함' : ''}`;
        totalValue.textContent = won(selected?.monthly);
        card.dataset.selectedMethod = selected?.method || 'promo';
        detail.innerHTML='';
        if (item.kidsPromo) { addRow(detail,'기기값','0원'); addRow(detail,'월 통신요금',won(selected?.service)); }
        else {
          addRow(detail,'월 기기값 · 이자 포함',won(selected?.inst?.monthly));
          addRow(detail,'할인 후 통신요금',won(selected?.service));
          if (selected?.method === 'support') addRow(detail,'적용 공시지원금','-' + won(selected.support));
          else addRow(detail,'선택약정 월 할인','-' + won(selected?.contractDiscount));
          if (item.welfare === 'basic_pension' && selected?.welfare?.amount) addRow(detail,'기초연금 수급자 할인','-' + won(selected.welfare.amount),'welfare-line');
          addRow(detail,'문자',item.p?.sms || '확인 필요');
        }
        choices.forEach(({button,status,quote}) => {
          const active=Boolean(quote?.known && quote.method===selected?.method), recommended=Boolean(quote?.known && quote.method===item.best?.method);
          button.classList.toggle('selected',active); button.setAttribute('aria-pressed',String(active));
          status.textContent=!quote?.known?'금액 확인 필요':active?(recommended?'추천 · 선택됨':'선택됨'):(recommended?'추천 · 선택하기':'선택하기');
        });
      }
      refresh(); target.append(card);
    });
    target.dataset.serverRecommend='1';
    document.documentElement.dataset.recommendApi='ready';
    setTimeout(()=>{applyingPurpose=false;},0);
  }

  async function syncPurpose() {
    const state=purposeState(), run=++purposeSeq;
    try { const data=await post('/recommend/purpose',state); if (run!==purposeSeq) return; renderPurpose(data,state); }
    catch { document.documentElement.dataset.recommendApi='fallback'; }
  }
  function schedulePurpose(delay=80) { clearTimeout(purposeTimer); purposeTimer=setTimeout(syncPurpose,delay); }

  function quickState() { return {carrier:$('quick-carrier')?.value || '', join_type:$('quick-join')?.value || '', brand:$('quick-brand')?.value || 'all', budget:$('quick-budget')?.value || 'light'}; }
  function renderQuick(data,state) {
    const target=$('quick-results'); if (!target) return; applyingQuick=true; target.innerHTML='';
    const items=Array.isArray(data.items)?data.items:[];
    if (!items.length) { target.append(el('p','','현재 조건에서 계산 가능한 조합을 찾지 못했습니다. 통신사·가입유형·브랜드를 한 단계 넓혀보세요.')); setTimeout(()=>{applyingQuick=false;},0); return; }
    const label=data.profile?.label || '선택한 월 부담';
    const note=$('quick-budget-note'); if (note) note.textContent=state.budget==='any'?'월 부담 제한 없이 현재 계산 가능한 조합을 넓게 비교합니다.':`${label}를 중심으로 보고, 정확히 맞는 조합이 부족하면 가장 가까운 조건까지 함께 비교합니다.`;
    items.forEach(item=>{
      const card=el('article','quick-result-card'); card.append(el('span','quick-result-badge',item.badge || '추천 조합'));
      const picture=imageFor(item.d,'quick-device-image'); if (picture) card.append(picture);
      card.append(el('strong','',item.d?.name || '휴대폰'), el('em','',`${item.p?.name || '요금제 확인'} · 요금제 ${won(item.p?.monthly_fee)}`));
      const specs=el('div','quick-plan-specs'); [['데이터',item.p?.data],['통화',item.p?.voice],['문자',item.p?.sms]].forEach(([l,v])=>{const s=el('span');s.append(el('small','',l),el('b','',v || '확인 필요'));specs.append(s);}); card.append(specs);
      const price=el('div','quick-result-price'); price.append(el('small','','예상 월 납부액'),el('b','',won(item.best?.monthly))); card.append(price);
      const method=item.best?.method==='support'?'공시지원금':'선택약정 25%'; card.append(el('small','quick-result-reason',`${method} 기준 · ${item.reason || '현재 조건에 맞는 조합'}\n${item.in_band ? label : '선택 부담대에 가까운 조건'}`));
      const button=el('button','','이 조건으로 자세히 계산'); button.type='button'; button.addEventListener('click',()=>openDirect(item,state.join_type)); card.append(button); target.append(card);
    });
    document.documentElement.dataset.recommendApi='ready'; setTimeout(()=>{applyingQuick=false;},0);
  }
  async function syncQuick() { const state=quickState(); if (!state.carrier || !state.join_type) return; const run=++quickSeq; try { const data=await post('/recommend/quick',state); if (run!==quickSeq) return; renderQuick(data,state); } catch { document.documentElement.dataset.recommendApi='fallback'; } }

  function init() {
    const purposeResults=$('purpose-results'), quickResults=$('quick-results'); if (!purposeResults && !quickResults) return;
    document.querySelectorAll('[data-purpose-category]').forEach(button=>button.addEventListener('click',()=>setTimeout(()=>schedulePurpose(20),0)));
    ['purpose-carrier','purpose-join','purpose-pension'].forEach(id=>$(id)?.addEventListener('change',()=>schedulePurpose(20)));
    document.querySelectorAll('[data-mobile-mode]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.mobileMode==='purpose')schedulePurpose(20);}));
    $('quick-find')?.addEventListener('click',()=>setTimeout(syncQuick,0));
    if (purposeResults) new MutationObserver(()=>{if(!applyingPurpose && !purposeResults.dataset.serverRecommend)schedulePurpose(90);}).observe(purposeResults,{childList:true,subtree:true});
    if (quickResults) new MutationObserver(()=>{if(!applyingQuick && quickResults.querySelector('.quick-result-card'))setTimeout(syncQuick,60);}).observe(quickResults,{childList:true,subtree:true});
    schedulePurpose(900);
  }
  if (document.readyState==='loading') document.addEventListener('DOMContentLoaded',init,{once:true}); else init();
})();
